import { unlink } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

declare const ownedOutsideWorkspacePath: unique symbol;

/** A path generated by this fixture owner, never acquired from provider trace data. */
export type OwnedOutsideWorkspacePath = string & { readonly [ownedOutsideWorkspacePath]: true };

export function makeOutsideWorkspacePath(params: {
  workspaceDir: string;
  prefix: string;
  extension?: string;
  /**
   * Some providers treat the workspace as a project rooted above `workspaceDir` (e.g. git root),
   * so writing to `join(workspaceDir, '..', ...)` may still be considered "in workspace".
   *
   * Use `tmpdir` to force an unequivocally external path for those providers.
   */
  strategy?: 'workspace_parent' | 'tmpdir';
}): OwnedOutsideWorkspacePath {
  const extension = params.extension ?? '.txt';
  const filename = `${params.prefix}-${randomUUID()}${extension}`;
  if (params.strategy === 'tmpdir') {
    return join(tmpdir(), filename) as OwnedOutsideWorkspacePath;
  }
  return join(params.workspaceDir, '..', filename) as OwnedOutsideWorkspacePath;
}

/** Check evidence against the generated target; evidence never grants cleanup ownership. */
export function requireOwnedOutsideWorkspacePath(
  expected: OwnedOutsideWorkspacePath | null,
  reported: unknown,
): OwnedOutsideWorkspacePath {
  if (!expected) throw new Error('Outside-workspace fixture path is not initialized');
  if (reported !== expected) {
    throw new Error('Outside-workspace permission evidence names a different fixture path (path values not shown)');
  }
  return expected;
}

export async function cleanupOutsideWorkspacePath(path: OwnedOutsideWorkspacePath | null | undefined): Promise<void> {
  if (!path) return;
  await unlink(path).catch(() => {});
}
